Aiyagari1994.zeroRate_cap_change_exact:
Aiyagari1994.zeroRate_cap_change_exact (m : Aiyagari1994.HouseholdPrimitives)
  (hsmooth : Aiyagari1994.UtilitySmooth m.utility) (hcurvature : Aiyagari1994.UtilityCurvature m.utility)
  (hnd : Aiyagari1994.IncomeNondegenerate m.income) (b₁ b₂ : ℝ) (hb₁ : 0 ≤ b₁) (hb₂ : 0 ≤ b₂) (w : ℝ) (hw : 0 < w) :
  let m₁ := Aiyagari1994.M10B1.zeroRateHousehold m b₁ hb₁ w hw;
  let m₂ := Aiyagari1994.M10B1.zeroRateHousehold m b₂ hb₂ w hw;
  have h₁ := ⋯;
  have h₂ := ⋯;
  have pi₁ := Aiyagari1994.M06C.stationaryLaw m₁ hsmooth hcurvature hnd h₁;
  have pi₂ := Aiyagari1994.M06C.stationaryLaw m₂ hsmooth hcurvature hnd h₂;
  m₁ = m₂ ∧
    Aiyagari1994.valueFunction m₁ = Aiyagari1994.valueFunction m₂ ∧
      Aiyagari1994.assetPolicy m₁ = Aiyagari1994.assetPolicy m₂ ∧
        Aiyagari1994.consumptionPolicy m₁ = Aiyagari1994.consumptionPolicy m₂ ∧
          pi₁ = pi₂ ∧
            Aiyagari1994.stationaryAssetSupply m₂ b₂ pi₂ - Aiyagari1994.stationaryAssetSupply m₁ b₁ pi₁ = -(b₂ - b₁)
